async def act(page):
    """
    Download the full Orders CSV via the admin export endpoint, parse it, count cancelled orders by customer email,
    and print exactly: "email, name, phone" for the customer with the most cancellations. If the result cannot be
    determined, print an empty line.

    Notes:
    - Use a relative goto to '/index.php/admin/sales_order/exportCsv/' and wrap it in page.expect_download()
      because this endpoint triggers a browser download.
    - Do NOT change interface language settings.
    - Knowledge-base helpers were considered but not used because none provide a full historical Orders export
      including order statuses.
    """
    import io
    import csv
    import tempfile
    import os

    # Trigger and capture the download produced by the Orders CSV export endpoint.
    try:
        async with page.expect_download(timeout=120000) as dl_info:
            # This navigation triggers a file download; keep it as the last page action that navigates away.
            await page.goto('/index.php/admin/sales_order/exportCsv/')
        download = await dl_info.value
    except Exception:
        # Could not capture download; nothing to parse
        print("")
        return

    # Save download to a temporary file
    tmp = tempfile.NamedTemporaryFile(delete=False, suffix='.csv')
    tmp_path = tmp.name
    tmp.close()
    try:
        await download.save_as(tmp_path)
    except Exception:
        # Fallback: try to obtain a path from the Download object if supported
        try:
            path = await download.path()
            if path:
                tmp_path = path
            else:
                print("")
                return
        except Exception:
            print("")
            return

    # Read bytes and decode with fallbacks (UTF-8 w/ BOM first, then latin-1)
    try:
        with open(tmp_path, 'rb') as f:
            raw = f.read()
        try:
            csv_text = raw.decode('utf-8-sig')
        except Exception:
            csv_text = raw.decode('latin-1')
    except Exception:
        print("")
        try:
            os.unlink(tmp_path)
        except Exception:
            pass
        return

    # Parse CSV
    try:
        csv_file = io.StringIO(csv_text)
        reader = csv.DictReader(csv_file)
    except Exception:
        print("")
        try:
            os.unlink(tmp_path)
        except Exception:
            pass
        return

    # Aggregation
    cancellation_counts = {}
    customer_info = {}  # email -> (name, phone)

    # Helper: find first non-empty value where header contains any substring (case-insensitive)
    def find_value_by_substrings(lower_map, substrings):
        for h, v in lower_map.items():
            if v is None:
                continue
            for sub in substrings:
                if sub in h:
                    s = str(v).strip()
                    if s:
                        return s
        return ''

    # Helper: assemble a name from firstname/lastname parts if a single-field name not available
    def build_name_from_parts(lower_map):
        first = find_value_by_substrings(lower_map, ['billing firstname', 'billing_firstname', 'customer firstname', 'customer_firstname', 'firstname'])
        last = find_value_by_substrings(lower_map, ['billing lastname', 'billing_lastname', 'customer lastname', 'customer_lastname', 'lastname'])
        if first or last:
            return ' '.join([p for p in (first.strip(), last.strip()) if p])
        return ''

    # Iterate rows
    for row in reader:
        # Create lowercase-key mapping for header substring matching
        lower_map = { (k.lower() if k is not None else ''): (v if v is not None else '') for k, v in row.items() }

        status = find_value_by_substrings(lower_map, ['status', 'order status', 'state'])
        if not status:
            continue
        if status.strip().lower() not in ('canceled', 'cancelled'):
            continue

        email = find_value_by_substrings(lower_map, ['customer email', 'billing email', 'email', 'customer_email', 'billing_email'])
        if not email:
            # Skip orders without an email to aggregate on
            continue

        cancellation_counts[email] = cancellation_counts.get(email, 0) + 1

        if email not in customer_info:
            name = find_value_by_substrings(lower_map, ['bill to name', 'billing name', 'billing_name', 'customer name', 'name'])
            if not name:
                name = build_name_from_parts(lower_map)
            phone = find_value_by_substrings(lower_map, ['telephone', 'phone', 'billing telephone', 'billing_telephone'])
            customer_info[email] = (name, phone)

    # Clean up the temporary file
    try:
        os.unlink(tmp_path)
    except Exception:
        pass

    if not cancellation_counts:
        print("")
        return

    # Determine top email by cancellations
    top_email = max(cancellation_counts.items(), key=lambda kv: kv[1])[0]
    top_name, top_phone = customer_info.get(top_email, ('', ''))

    # Print exactly the requested output
    print(f"{top_email}, {top_name}, {top_phone}")

